def smallestDistinctSubsequence(s):
    last = {ch: i for i, ch in enumerate(s)}
    stack = []
    on_stack = set()
    for i, ch in enumerate(s):
        if ch in on_stack:
            continue
        while stack and stack[-1] > ch and last[stack[-1]] > i:
            on_stack.discard(stack.pop())
        stack.append(ch)
        on_stack.add(ch)
    return "".join(stack)
